parameters.jsCode:
// Baut je offener Agentur genau EINEN Beratungsauftrag.
// Bereich A kommt ausschliesslich aus bkBelegbasis() - derselben Funktion, mit
// der der Pruefer spaeter belegt/nicht belegt entscheidet.
// Alte Beratungsergebnisse werden NICHT mehr als Faktenquelle eingespeist.

// ===================== BELEG-KERN v1 =====================
// Einzige Quelle der Wahrheit fuer Datenreinigung, Belegbasis und Ableitungsregeln.
// Dieser Block wird von baue.js WOERTLICH in beide Code-Knoten eingesetzt:
//   "Kandidaten und Prompt bauen"  und  "Beratung auswerten".
// Aenderungen ausschliesslich hier vornehmen, danach baue.js laufen lassen.
// preflight.js prueft, dass beide Knoten denselben Block enthalten.

// Modelle und Tabellen liefern Umlaute teilweise zerlegt (o + U+0308 statt oe).
// Ohne Normalisierung trifft kein Muster mit Umlaut - "koenntest" wird erkannt,
// "könntest" nicht. Deshalb wird JEDER Text zuerst nach NFC zusammengezogen.
function bkNfc(v) {
  var s = String(v == null ? '' : v);
  try { return s.normalize('NFC'); } catch (e) { return s; }
}

function bkText(v) {
  return bkNfc(v).replace(/ /g, ' ').replace(/\s+/g, ' ').trim();
}

// ---- Analyse- und Meta-Etiketten -----------------------------------------
// Diese Etiketten stehen in den M3-Feldern und leiten unsere EIGENE Bewertung
// oder eine Recherchenotiz ein - keinen Firmenfakt. Ab dem Etikett bis zum Ende
// des Blocks gehoert der Text nicht mehr in die Firmenfakten.
var BK_ANALYSE = [
  /Passung f(?:ü|ue)r Jerome\s*:/i,
  /Umsetzungsn(?:ä|ae)he laut M2\s*:/i,
  /laut M2\s*:/i,
  /laut M4\s*:/i,
  /aus M1KI\s*:/i,
  /Gr(?:ö|oe)(?:ß|ss)te Chance\s*:/i,
  /Gr(?:ö|oe)(?:ß|ss)tes Risiko\s*:/i,
  /Fachlicher Fit\s*:/i,
  /Lernchance\s*:/i,
  /Lernwert\s*:/i,
  /Eignung\s*:/i,
  // Bewerberperspektive ohne Namensnennung
  /Ein(?:e)?\s+Quereinsteiger\w*/i,
  /F(?:ü|ue)r\s+(?:einen|eine)\s+(?:Quereinsteiger|Einsteiger|Bewerber)\w*/i
];

var BK_META = [
  /manuell verifiziert/i,
  /\d+\s+von\s+\d+\s+gepr(?:ü|ue)ften Firmenseiten/i,
  /\d+\s+Unterseite\(?n?\)?\s+als Catch-all/i,
  /Quellen\s*:\s*https?:/i,
  /Karriereseite vorhanden\s*:/i,
  /laut Datensatz\s*:/i,
  /Stand der Recherche\s*:/i,
  /Nur informativ/i
];

// ---- Navigationswortschatz ------------------------------------------------
// Ein Segment gilt als Menue, wenn es ueberwiegend aus diesen Woertern besteht.
// Einzelne Treffer schaden nicht - erst der Anteil entscheidet.
var BK_NAV_WORT = ('zum inhalt springen skip to content cookie cookies einstellungen startseite start home impressum '
  + 'datenschutz datenschutzerklaerung agb kontakt kontaktformular menue menu navigation suchen suche login anmelden '
  + 'leistungen referenzen kompetenzen vorgehen produkt produkte unternehmen team labor karriere blog news presse faq '
  + 'ueber uber uns de en deutsch english sprache mehr erfahren weiterlesen jetzt hier klicken nach oben seite '
  + 'anfragen erstberatung vorprojekt beratungsgespraech termin demo angebot prozess prozesse tools services '
  + 'portfolio loesungen branchen partner downloads newsletter').split(' ');

var BK_NAV_SET = {};
for (var bkI = 0; bkI < BK_NAV_WORT.length; bkI++) {
  BK_NAV_SET[BK_NAV_WORT[bkI]] = true;
}

var BK_NAV_PHRASE = /zum inhalt springen|skip to content|cookie[- ]?einstellung|cookie[- ]?hinweis|alle akzeptieren|nach oben scrollen/i;

// ---- Verneinung -----------------------------------------------------------
// Wirkt ab jetzt NUR noch auf das Segment, in dem sie steht.
var BK_NEGATIV = /nicht ersichtlich|nicht bekannt|nicht belegt|nicht nachweisbar|nicht gesichert|nicht dokumentiert|nicht klar|nicht vollst(?:ä|ae)ndig belegt|nichts belegt|nichts bekannt|nichts gesichert|nichts dokumentiert|l(?:ä|ae)sst sich (?:bisher |derzeit |aktuell |so )?nicht sagen|unbekannt|unklar|keine angaben|keine konkreten|keine information|bleibt offen|ist offen|fraglich/i;

// ---- Ableitungskennzeichen ------------------------------------------------
// Prompt und Pruefer benutzen exakt diese Liste. Ein Satz ueber Jeromes
// moegliche Arbeit MUSS eines dieser Woerter enthalten.
var BK_ABLEITUNG = /\b(k(?:ö|oe)nnte(?:st|n|t)?|w(?:ü|ue)rde(?:st|n|t)?|w(?:ä|ae)re(?:n|st)?|d(?:ü|ue)rfte(?:st|n)?|m(?:ü|ue)sste(?:st|n)?|h(?:ä|ae)tte(?:st|n)?|wahrscheinlich|vermutlich|m(?:ö|oe)glicherweise|denkbar|naheliegend|voraussichtlich|anzunehmen|vorstellbar|nahe liegen)\b/i;

// Formulierungen, die auch mit Kennzeichen eine Tatsache behaupten.
var BK_ABSOLUT = /\bdein (?:arbeits)?alltag (?:ist|sieht|besteht)\b|\bf(?:ü|ue)r dich sieht der (?:tag|alltag)\b|\bdu musst\b|\bdu wirst\b|\bdu bist dann\b|\bdeine aufgabe ist\b/i;

// Taetigkeitsaussage ueber Jerome.
var BK_TAETIGKEIT = /\b(?:du|dein\w*)\b[^.!?]{0,120}\b(?:arbeitest|arbeiten|baust|bauen|entwickelst|entwickeln|umsetzt|umsetzen|programmierst|programmieren|testest|testen|dokumentierst|dokumentieren|betreust|betreuen|verantwortest|verantworten|einsetzt|einsetzen|anbindest|anbinden|erkennst|weiterentwickelst|lernst|mitarbeitest)\b/i;

// Belegte Rolle. "Karriereseite" ist ausdruecklich KEIN Rollenbeleg -
// eine vorhandene Karriereseite sagt nichts ueber eine passende offene Stelle.
var BK_ROLLE = /stellenausschreibung|stellenangebot|offene stelle|ausgeschriebene stelle|position ausgeschrieben|vakanz|wir suchen (?:ab|zum|einen|eine|dich|verst(?:ä|ae)rkung)|bewirb dich|werkstudent|praktikumsplatz|junior[- ]?(?:entwickler|berater|consultant|developer)/i;

// ---- Segmentierung --------------------------------------------------------
// Rohfeld -> Bloecke (an " | ") -> Segmente (an Satzenden und Punktketten).
function bkBloecke(v) {
  return bkText(v)
    .split(/\s*\|\s*/)
    .map(function (s) { return s.trim(); })
    .filter(function (s) { return s; });
}

function bkSegmenteAusBlock(block) {
  return String(block)
    .split(/(?<=[.!?])\s+|\s+·\s+|\s+—\s+|\s+–\s+|(?:\s*\.\s*){2,}/)
    .map(function (s) {
      return s
        .replace(/^[\s.,;:·—–-]+/, '')
        .replace(/[\s.,;:·—–-]+$/, '')
        .trim();
    })
    .filter(function (s) { return s; });
}

function bkIstNavigation(seg) {
  var s = String(seg);

  if (BK_NAV_PHRASE.test(s)) {
    return true;
  }

  var w = s
    .toLowerCase()
    .replace(/[^a-z0-9äöüß\s/-]/g, ' ')
    .split(/\s+/)
    .filter(function (x) { return x; });

  if (!w.length) {
    return true;
  }

  var nav = 0;

  for (var i = 0; i < w.length; i++) {
    if (BK_NAV_SET[w[i]]) {
      nav++;
    }
  }

  var anteil = nav / w.length;

  if (anteil >= 0.7) {
    return true;
  }

  if (w.length <= 12 && anteil >= 0.5) {
    return true;
  }

  // Reine Ziffern- oder Zeichenfragmente aus dem Seitenaufbau.
  if (/^[0-9\W_]+$/.test(s)) {
    return true;
  }

  return false;
}

// Kernfunktion. Liefert die drei Anteile eines Rohfeldes getrennt zurueck.
//   rein    - Firmenfakten, ohne Navigation, ohne Analyse, ohne Meta, ohne Verneinung
//   analyse - unsere eigene Bewertung (gehoert nach B)
//   meta    - Recherchenotizen (gehoeren nirgendwohin)
//   offen   - Segmente mit ausdruecklicher Verneinung (gehoeren nach C)
//   nav     - verworfene Menuesegmente, nur zur Messung
function bkTrenne(v) {
  var rein = [];
  var analyse = [];
  var meta = [];
  var offen = [];
  var nav = [];

  var bloecke = bkBloecke(v);

  for (var b = 0; b < bloecke.length; b++) {
    var block = bloecke[b];

    // Analyse- und Meta-Etikett schneidet den Rest des Blocks ab.
    var schnitt = -1;
    var artSchnitt = '';

    for (var a = 0; a < BK_ANALYSE.length; a++) {
      var m = block.match(BK_ANALYSE[a]);

      if (m && (schnitt === -1 || m.index < schnitt)) {
        schnitt = m.index;
        artSchnitt = 'analyse';
      }
    }

    for (var t = 0; t < BK_META.length; t++) {
      var m2 = block.match(BK_META[t]);

      if (m2 && (schnitt === -1 || m2.index < schnitt)) {
        schnitt = m2.index;
        artSchnitt = 'meta';
      }
    }

    var kopf = block;
    var rest = '';

    if (schnitt >= 0) {
      kopf = block.slice(0, schnitt);
      rest = block.slice(schnitt);
    }

    if (rest) {
      (artSchnitt === 'meta' ? meta : analyse).push(rest.trim());
    }

    var segs = bkSegmenteAusBlock(kopf);

    // Der Schnitt kann einen angefangenen Satz hinterlassen ("Sitz" aus
    // "Sitz laut Datensatz: Koeln"). Ein solcher Rest ist kein Firmenfakt.
    if (schnitt >= 0 && segs.length) {
      var letzt = segs[segs.length - 1]
        .split(/\s+/)
        .filter(function (x) { return x; });

      if (letzt.length <= 2) {
        segs.pop();
      }
    }

    for (var s = 0; s < segs.length; s++) {
      var seg = segs[s];

      if (bkIstNavigation(seg)) {
        nav.push(seg);
        continue;
      }

      if (BK_NEGATIV.test(seg)) {
        offen.push(seg);
        continue;
      }

      rein.push(seg);
    }
  }

  return {
    rein: bkEindeutig(rein),
    analyse: bkEindeutig(analyse),
    meta: bkEindeutig(meta),
    offen: bkEindeutig(offen),
    nav: nav
  };
}

// Wiederholungen entfernen. Ersetzt die alte Eindeutigkeitsquote.
function bkEindeutig(liste) {
  var gesehen = {};
  var out = [];

  for (var i = 0; i < liste.length; i++) {
    var k = liste[i]
      .toLowerCase()
      .replace(/[^a-z0-9äöüß]/g, '');

    if (!k || gesehen[k]) {
      continue;
    }

    gesehen[k] = true;
    out.push(liste[i]);
  }

  return out;
}

// Gereinigter Fliesstext eines Feldes.
function bkSauber(v) {
  return bkTrenne(v).rein.join('. ');
}

// ---- Feldlisten -----------------------------------------------------------
// EINE Liste fuer Bereich A und fuer die Belegbasis des Pruefers.
// Aendert sich hier etwas, aendert es sich fuer beide gleichzeitig.
var BK_FIRMENFELDER = [
  ['Rechtlicher Firmenname', 'm3b_rechtlicher_firmenname', 200],
  ['Firmenkern', 'm3a_firmenkern', 1600],
  ['Angebotene Leistungen', 'm3a_angebotene_leistungen', 1200],
  ['Leistungen laut Website', 'm3b_leistungen', 1600],
  ['Automatisierungsfokus', 'm3a_automatisierungsfokus', 600],
  ['Kundennutzen', 'm3a_kundennutzen', 500],
  ['Umsetzungsbelege', 'm3a_umsetzungsbelege', 400],
  ['Umsetzungsbelege laut Website', 'm3b_umsetzungsbelege', 400],
  ['Projekte und Referenzen', 'm3b_projekte_referenzen', 1600],
  ['Anknuepfungspunkte', 'm3b_anknuepfungspunkte', 400],
  ['Hinweis zum Team', 'm3b_team_hinweis', 300],
  ['Technologien laut M3A', 'm3a_technologien', 400],
  ['Technologien laut Website', 'm3b_technologien', 400]
];

// Baut Firmenfakten, Belegtext und offene Punkte in einem Durchgang.
// Prompt und Pruefer rufen ausschliesslich diese Funktion auf.
function bkBelegbasis(a) {
  var fakten = [];
  var belegTeile = [];
  var offen = [];
  var analyse = [];
  var verworfen = [];
  var gesehen = {};

  for (var i = 0; i < BK_FIRMENFELDER.length; i++) {
    var bez = BK_FIRMENFELDER[i][0];
    var feld = BK_FIRMENFELDER[i][1];
    var limit = BK_FIRMENFELDER[i][2];

    var teil = bkTrenne(a ? a[feld] : '');

    for (var x = 0; x < teil.analyse.length; x++) {
      analyse.push(teil.analyse[x]);
    }

    for (var y = 0; y < teil.offen.length; y++) {
      offen.push(bez + ': ' + teil.offen[y]);
    }

    if (teil.nav.length) {
      verworfen.push(bez + ': ' + teil.nav.length + ' Menuesegment(e)');
    }

    if (!teil.rein.length) {
      continue;
    }

    // Doppelte Segmente ueber Feldgrenzen hinweg nur einmal aufnehmen.
    var neu = [];

    for (var z = 0; z < teil.rein.length; z++) {
      var k = teil.rein[z]
        .toLowerCase()
        .replace(/[^a-z0-9äöüß]/g, '');

      if (gesehen[k]) {
        continue;
      }

      gesehen[k] = true;
      neu.push(teil.rein[z]);
    }

    if (!neu.length) {
      continue;
    }

    var text = neu.join('. ');

    if (text.length > limit) {
      text = text.slice(0, limit) + ' ...';
    }

    fakten.push(bez + ': ' + text);
    belegTeile.push(text);
  }

  return {
    fakten: fakten,
    belegText: belegTeile.join(' ').toLowerCase(),
    offen: bkEindeutig(offen),
    analyse: bkEindeutig(analyse),
    verworfen: verworfen
  };
}

// Ist eine Rolle bei dieser Firma belegt? Geprueft wird ausschliesslich der
// gereinigte Belegtext, damit Recherchenotizen nichts ausloesen koennen.
function bkRolleBelegt(belegText) {
  return BK_ROLLE.test(bkNfc(belegText));
}

// Eine Frage oder ein offener Punkt ist keine Behauptung. "Ob du remote
// arbeiten kannst, solltest du nachfragen" ist kein Verstoss.
var BK_FRAGE = /\bob\b|\?|nachfragen|nachhaken|kl(?:ä|ae)ren|offene(?:r|s)? (?:punkt|frage)/i;

// Saetze eines Textes.
function bkSaetze(text) {
  return bkNfc(text)
    .split(/(?<=[.!?])\s+/)
    .map(function (s) { return s.trim(); })
    .filter(function (s) { return s; });
}

// Eine Aussage ueber Jeromes moegliche Arbeit ist zulaessig, wenn der Satz ein
// Ableitungskennzeichen traegt und keine absolute Wendung enthaelt.
function bkAbleitungOk(roh) {
  var satz = bkNfc(roh);

  if (BK_ABSOLUT.test(satz)) {
    return false;
  }

  return BK_ABLEITUNG.test(satz);
}

// Nebensaetze wie "ohne dass du programmieren musst" beschreiben eine
// Eigenschaft des Werkzeugs, keine Taetigkeit Jeromes bei dieser Firma.
var BK_NEBENSATZ = /\bohne (?:dass |zu )|\bstatt dass du\b|\bsodass du nicht\b|\bdamit du nicht\b/i;

// Solche Nebensaetze aus dem Satz nehmen, bevor auf Taetigkeit geprueft wird.
function bkOhneNebensaetze(satz) {
  return String(satz)
    .split(/[,;–—]| aber | jedoch | sondern /i)
    .filter(function (t) {
      return !BK_NEBENSATZ.test(t);
    })
    .join(' ');
}

// Verstoss gegen die Ableitungsregel: der Satz behauptet eine Taetigkeit,
// ist keine Frage und kein offener Punkt - und traegt trotzdem kein Kennzeichen.
// Prompt-Regel und Prueferregel sind damit dieselbe Regel.
function bkTaetigkeitsverstoss(roh) {
  var s = bkNfc(roh);

  if (BK_ABSOLUT.test(s)) {
    return false;
  }

  if (BK_NEGATIV.test(s) || BK_FRAGE.test(s)) {
    return false;
  }

  if (!BK_TAETIGKEIT.test(bkOhneNebensaetze(s))) {
    return false;
  }

  return !BK_ABLEITUNG.test(s);
}

// ---- Erklaerung ist keine Zuschreibung ------------------------------------
// "On-Premise bedeutet, dass die Loesung im Unternehmen laeuft und nicht in der
// Cloud" erklaert einen Fachbegriff. Es behauptet nichts ueber DIESE Firma.
// Sobald sich der Satz auf die Firma bezieht, gilt die Ausnahme nicht mehr.
var BK_ERKLAERUNG = /\bbedeutet\b|\bbedeuten\b|\bhei(?:ß|ss)t\b|\bd\.h\.|\bsprich\b|\bgemeint ist\b|\bversteht man\b|\bnennt man\b|(?:ä|ae)hnlich|vergleichbar|so wie|wie zum beispiel|zum beispiel|etwa wie|analog zu/i;
var BK_FIRMENBEZUG = /\bhier\b|\bdort\b|\bbei ihnen\b|\bbei denen\b|\bin diesem fall\b|\bin ihrem fall\b/i;

function bkIstErklaerung(roh, firma) {
  var s = bkNfc(roh);

  if (!BK_ERKLAERUNG.test(s)) {
    return false;
  }

  if (BK_FIRMENBEZUG.test(s)) {
    return false;
  }

  var f = bkNfc(firma).trim().toLowerCase();

  if (f && s.toLowerCase().indexOf(f) !== -1) {
    return false;
  }

  return true;
}

// ---- JSON aus einer Modellantwort -----------------------------------------
// Steht in beiden Knoten, die eine Modellantwort lesen ("Laenge pruefen" und
// "Beratung auswerten"). Vorher hatte jeder Knoten seine eigene Fassung - der
// Laengenknoten konnte eine Antwort mit echtem Zeilenumbruch nicht lesen und
// hat die Laengenkorrektur stillschweigend uebersprungen.
function bkAlleJson(t) {
  var gefunden = [];
  var i = 0;

  while (true) {
    var a = t.indexOf('{', i);

    if (a === -1) {
      break;
    }

    var tiefe = 0;
    var imText = false;
    var esc = false;
    var ende = -1;

    for (var k = a; k < t.length; k++) {
      var ch = t[k];

      if (esc) {
        esc = false;
        continue;
      }

      if (ch === '\\') {
        if (imText) {
          esc = true;
        }
        continue;
      }

      if (ch === '"') {
        imText = !imText;
        continue;
      }

      if (imText) {
        continue;
      }

      if (ch === '{') {
        tiefe++;
      } else if (ch === '}') {
        tiefe--;

        if (tiefe === 0) {
          ende = k;
          break;
        }
      }
    }

    if (ende === -1) {
      break;
    }

    gefunden.push(t.slice(a, ende + 1));
    i = ende + 1;
  }

  return gefunden;
}

// GPT setzt Absaetze als echten Zeilenumbruch mitten in den JSON-String.
// JSON.parse bricht dann ab. Steuerzeichen INNERHALB von Zeichenketten werden
// deshalb nachtraeglich escaped. Ausserhalb bleibt alles unveraendert.
function bkSteuerzeichen(roh) {
  var out = '';
  var imText = false;
  var esc = false;

  for (var i = 0; i < roh.length; i++) {
    var ch = roh[i];
    var code = roh.charCodeAt(i);

    if (esc) {
      out += ch;
      esc = false;
      continue;
    }

    if (ch === '\\') {
      out += ch;

      if (imText) {
        esc = true;
      }

      continue;
    }

    if (ch === '"') {
      imText = !imText;
      out += ch;
      continue;
    }

    if (imText && code < 32) {
      out += (
        ch === '\n' ? '\\n'
          : ch === '\r' ? '\\r'
          : ch === '\t' ? '\\t'
          : ' '
      );
      continue;
    }

    out += ch;
  }

  return out;
}

// Liefert das zusammengefuehrte Antwortobjekt oder null.
function bkJsonParse(t) {
  if (t && typeof t === 'object') {
    return t;
  }

  if (typeof t !== 'string') {
    return null;
  }

  var ziel = {};
  var etwas = false;
  var liste = bkAlleJson(t);

  for (var i = 0; i < liste.length; i++) {
    var o = null;

    try {
      o = JSON.parse(liste[i]);
    } catch (e) {
      try {
        o = JSON.parse(bkSteuerzeichen(liste[i]));
      } catch (e2) {
        continue;
      }
    }

    if (!o || typeof o !== 'object' || Array.isArray(o)) {
      continue;
    }

    etwas = true;

    var keys = Object.keys(o);

    for (var k = 0; k < keys.length; k++) {
      var key = keys[k];
      var alt = ziel[key];
      var neu = o[key];

      var leer =
        alt === undefined ||
        alt === '' ||
        (Array.isArray(alt) && alt.length === 0);

      if (leer && neu !== undefined && neu !== '') {
        ziel[key] = neu;
      }
    }
  }

  return etwas && ziel.berater_text !== undefined
    ? ziel
    : null;
}

// Rohtext aus einer n8n-OpenAI-Antwort holen. Ebenfalls in beiden Knoten gleich.
function bkRohtext(row) {
  var g = [];

  function add(v) {
    if (v == null || v === '') {
      return;
    }

    if (typeof v === 'string') {
      var t = v.trim();

      if (t) {
        g.push(t);
      }

      return;
    }

    if (Array.isArray(v)) {
      for (var i = 0; i < v.length; i++) {
        add(v[i]);
      }

      return;
    }

    if (typeof v !== 'object') {
      return;
    }

    var felder = [
      'output_text',
      'text',
      'message',
      'response',
      'data',
      'result',
      'content'
    ];

    for (var f = 0; f < felder.length; f++) {
      if (v[felder[f]] !== undefined) {
        add(v[felder[f]]);
      }
    }

    if (Array.isArray(v.output)) {
      for (var o = 0; o < v.output.length; o++) {
        add(v.output[o]);
      }
    }
  }

  var oben = [
    'output_text',
    'output',
    'response',
    'data',
    'result',
    'content',
    'text'
  ];

  for (var i = 0; i < oben.length; i++) {
    add(row && row[oben[i]]);
  }

