// Baut Firmenfakten, Belegtext und offene Punkte in einem Durchgang.
// Prompt und Pruefer rufen ausschliesslich diese Funktion auf.
function bkBelegbasis(a) {
  var fakten = [], belegTeile = [], offen = [], analyse = [], verworfen = [];
  var gesehen = {};
  for (var i = 0; i < BK_FIRMENFELDER.length; i++) {
    var bez = BK_FIRMENFELDER[i][0], feld = BK_FIRMENFELDER[i][1], limit = BK_FIRMENFELDER[i][2];
    var teil = bkTrenne(a ? a[feld] : '');
    for (var x = 0; x < teil.analyse.length; x++) { analyse.push(teil.analyse[x]); }
    for (var y = 0; y < teil.offen.length; y++) { offen.push(bez + ': ' + teil.offen[y]); }
    if (teil.nav.length) { verworfen.push(bez + ': ' + teil.nav.length + ' Menuesegment(e)'); }
